auto capture=[&](S&s,int pi,bool&ok){std::vector<float>b(s.n+8),a(s.n+8);std::vector<uint8_t>m(s.n+32);ck(cudaMemcpy(b.data(),s.b,b.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(a.data(),s.a,a.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(m.data(),s.m,m.size(),cudaMemcpyDeviceToHost));ok&=memcmp(a.data(),s.ah.data(),a.size()*4)==0;for(int i=0;i<4;i++)ok&=bits(b[i])==bits(FSENT)&&bits(b[s.n+4+i])==bits(FSENT);for(int i=0;i<16;i++)ok&=m[i]==MSENT&&m[s.n+16+i]==MSENT;float scale=1.f/prob[pi];std::vector<uint32_t>out;out.reserve(2*s.n+48);for(int i=0;i<s.n;i++){size_t bit=s.base+pi*s.n+i;uint8_t keep=(packed[bit>>3]>>(bit&7))&1;float expected=s.ah[i+4]*float(keep)*scale;ok&=m[i+16]==keep&&bits(b[i+4])==bits(expected);out.push_back(bits(b[i+4]));}for(int i=0;i<s.n;i++)out.push_back(m[i+16]);for(auto*ptr:{b.data(),b.data()+s.n+4,a.data(),a.data()+s.n+4})for(int j=0;j<4;j++)out.push_back(bits(ptr[j]));for(int j=0;j<16;j++)out.push_back(m[j]);for(int j=0;j<16;j++)out.push_back(m[s.n+16+j]);return out;};
